{
  "summary": "Gather current contract terms, renewal/price-increase policy, SLA performance and any credits owed, and invoice/currency details for Acme Cloud Services, then draft a vendor response addressing the renewal and 12% increase.",
  "reply_type": "vendor_email",
  "steps": [
    {
      "id": 1,
      "agent": "retriever",
      "task": "List and read the current Acme Cloud Services contract (end date, current pricing, renewal terms, notice period), any internal pricing/renewal policy documents (e.g., max acceptable increase, escalation clauses), recent invoices to confirm current rate and currency, and SLA performance records; run the SLA credit calculator to determine any credits owed for missed SLAs; use the currency converter only if invoice/contract amounts are in a foreign currency like USD.",
      "why": "All facts about the contract terms, pricing history, policy limits, SLA performance, and any owed credits must be confirmed before responding to the renewal and price increase request."
    },
    {
      "id": 2,
      "agent": "executor",
      "task": "Draft the vendor email response to Acme Cloud Services acknowledging the contract end date, addressing the proposed 12% increase against internal policy limits, referencing any SLA credits owed, and proposing renewal terms or a counter-offer as appropriate.",
      "why": "The executor synthesizes the retrieved facts into the final reply for human review and approval."
    }
  ],
  "escalate": null
}
